package com.amitpariyar.thefirstcrush;

import android.app.*;
import android.os.Bundle;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.view.inputmethod.InputMethodManager;
import android.content.Context;
import android.widget.*;
import java.util.*;

public class MainActivity extends Activity {
 int pink=Color.rgb(229,55,137), purple=Color.rgb(117,81,211), ink=Color.rgb(38,35,55), muted=Color.rgb(132,128,148), bg=Color.rgb(247,246,250);
 LinearLayout root,body,top,bottom; String current="Home"; boolean logged=false; EditText postInput;
 ArrayList<String> feed=new ArrayList<>(Arrays.asList("Some people make ordinary days feel like a beautiful story. 💗","तिमी मुस्कुराउँदा मेरो दिन नै राम्रो हुन्छ। ❤️","Are you Wi-Fi? Because I’m feeling a connection."));
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.WHITE);getWindow().setNavigationBarColor(Color.WHITE);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);login();}
 GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(radius);return d;}
 TextView text(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(null,Typeface.BOLD);t.setPadding(0,5,0,5);return t;}
 LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
 LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(0);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
 void base(String title,boolean nav){root=column();root.setBackgroundColor(bg);setContentView(root);top=row();top.setPadding(18,12,14,12);top.setBackgroundColor(Color.WHITE);TextView brand=text("♡",30,pink,true);top.addView(brand);TextView heading=text(title,21,ink,true);LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(0,-2,1);hp.leftMargin=12;top.addView(heading,hp);if(title.equals("The First Crush")){top.addView(button("⌕",()->findFriends()));top.addView(button("♧",()->screen("Notifications")));}root.addView(top);ScrollView scroll=new ScrollView(this);body=column();body.setPadding(16,14,16,20);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));if(nav)bottomNav();}
 TextView button(String label,Runnable run){TextView b=text(label,17,purple,true);b.setGravity(Gravity.CENTER);b.setPadding(12,8,12,8);b.setOnClickListener(v->run.run());return b;}
 void bottomNav(){bottom=row();bottom.setPadding(5,7,5,7);bottom.setBackgroundColor(Color.WHITE);String[][] items={{"⌂","Home"},{"♧","Friends"},{"＋","Post"},{"♡","Alerts"},{"●","Profile"}};for(String[] it:items){LinearLayout cell=column();cell.setGravity(Gravity.CENTER);TextView icon=text(it[0],21,it[1].equals(current)?pink:muted,true);icon.setGravity(Gravity.CENTER);TextView label=text(it[1],10,it[1].equals(current)?pink:muted,true);label.setGravity(Gravity.CENTER);cell.addView(icon);cell.addView(label);bottom.addView(cell,new LinearLayout.LayoutParams(0,-2,1));cell.setOnClickListener(v->{if(it[1].equals("Post"))createPost();else screen(it[1].equals("Alerts")?"Notifications":it[1]);});}root.addView(bottom);}
 TextView action(String s,Runnable r){TextView t=text(s,15,purple,true);t.setGravity(Gravity.CENTER);t.setPadding(12,12,12,12);t.setBackground(shape(Color.WHITE,22));t.setOnClickListener(v->r.run());return t;}
 void login(){root=column();root.setGravity(Gravity.CENTER);root.setPadding(26,30,26,30);root.setBackground(new android.graphics.drawable.GradientDrawable(android.graphics.drawable.GradientDrawable.Orientation.TL_BR,new int[]{0xffffe5f0,0xffeee9ff,0xfffaf8fc}));setContentView(root);TextView logo=text("♡",68,pink,true);logo.setGravity(Gravity.CENTER);root.addView(logo);TextView title=text("The First Crush",30,ink,true);title.setGravity(Gravity.CENTER);root.addView(title);TextView sub=text("Your people. Your moments. Your story.",13,muted,false);sub.setGravity(Gravity.CENTER);root.addView(sub);EditText email=field("Email or username");EditText pass=field("Password");pass.setInputType(129);root.addView(email);root.addView(pass);root.addView(action("LOG IN",()->{logged=true;screen("Home");}));root.addView(action("CREATE ACCOUNT",()->signup()));}
 EditText field(String hint){EditText e=new EditText(this);e.setSingleLine(true);e.setHint(hint);e.setTextSize(15);e.setPadding(15,10,15,10);e.setBackground(shape(Color.WHITE,18));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,52);p.topMargin=10;e.setLayoutParams(p);return e;}
 void signup(){base("Create account",false);EditText name=field("Full name"),email=field("Email address"),password=field("Password");body.addView(name);body.addView(email);body.addView(password);body.addView(action("CREATE ACCOUNT",()->screen("Home")));body.addView(action("Back to login",()->login()));}
 void screen(String page){current=page;base(page.equals("Home")?"The First Crush":page,true);switch(page){case "Home":home();break;case "Friends":friends();break;case "Requests":requests();break;case "Notifications":notifications();break;case "Profile":profile();break;default:settings();}}
 void home(){body.addView(text("YOUR CIRCLE",18,ink,true));HorizontalScrollView stories=new HorizontalScrollView(this);LinearLayout sr=row();for(String s:new String[]{"＋\nYour story","💗\nRomantic","😂\nFunny","🇳🇵\nNepali","✨\nCute"}){TextView x=text(s,14,purple,true);x.setGravity(Gravity.CENTER);x.setPadding(14,14,14,14);sr.addView(x);}stories.addView(sr);body.addView(stories);body.addView(text("Community feed",22,ink,true));for(String p:feed)postCard("Community member",p);body.addView(action("＋  Create a post",()->createPost()));}
 void postCard(String author,String content){LinearLayout card=column();card.setPadding(15,12,15,10);card.setBackground(shape(Color.WHITE,22));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.topMargin=12;body.addView(card,cp);card.addView(text("♡  "+author+"     ·     Community",13,purple,true));TextView msg=text(content,17,ink,false);msg.setPadding(0,15,0,15);card.addView(msg);LinearLayout actions=row();TextView like=button("♡  Like",()->like.setText("♥  Liked"));actions.addView(like);actions.addView(button("Comment",()->new AlertDialog.Builder(this).setMessage("Comments will be available when community services are connected.").setPositiveButton("OK",null).show()));actions.addView(button("Share",()->{android.content.Intent i=new android.content.Intent(android.content.Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(android.content.Intent.EXTRA_TEXT,content);startActivity(android.content.Intent.createChooser(i,"Share post"));}));card.addView(actions);}
 void friends(){body.addView(text("Find people and grow your circle",14,muted,false));EditText search=field("Search name or username");body.addView(search);body.addView(action("Incoming friend requests",()->screen("Requests")));for(String n:new String[]{"Sujan Tamang","Aarav Sharma","Sanjana Rai","Riya Karki","Prabin Lama"}){LinearLayout r=row();r.addView(text("◉  "+n,16,ink,true),new LinearLayout.LayoutParams(0,-2,1));TextView add=button("＋ Add",()->{add.setText("Requested");});r.addView(add);body.addView(r);body.addView(divider());}}
 void requests(){body.addView(text("Friend requests",22,ink,true));for(String n:new String[]{"Nisha Gurung","Suman Thapa","Anisha Shrestha"}){LinearLayout r=row();r.addView(text(n,16,ink,true),new LinearLayout.LayoutParams(0,-2,1));r.addView(button("Accept",()->{}));r.addView(button("Decline",()->{}));body.addView(r);body.addView(divider());}}
 void notifications(){for(String n:new String[]{"💗  Someone liked your post","👋  New friend request","💬  Someone commented on your post","✨  Welcome to The First Crush"}){body.addView(text(n,16,ink,false));body.addView(divider());}}
 void profile(){TextView avatar=text("A",42,Color.WHITE,true);avatar.setGravity(Gravity.CENTER);avatar.setBackground(shape(purple,90));LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(100,100);ap.gravity=Gravity.CENTER;body.addView(avatar,ap);TextView name=text("Your Name",23,ink,true);name.setGravity(Gravity.CENTER);body.addView(name);TextView handle=text("@yourusername",13,muted,false);handle.setGravity(Gravity.CENTER);body.addView(handle);body.addView(text("0 Posts        0 Friends        0 Following",15,purple,true));body.addView(action("Edit profile",()->editProfile()));body.addView(action("Settings",()->screen("Settings")));body.addView(text("Your posts",20,ink,true));body.addView(text("Your shared posts will appear here.",14,muted,false));}
 void editProfile(){base("Edit profile",false);EditText name=field("Display name"),bio=field("Bio");body.addView(name);body.addView(bio);body.addView(action("Save changes",()->screen("Profile")));}
 void settings(){body.addView(action("Account and privacy",()->{}));body.addView(action("Blocked users",()->{}));body.addView(action("Help and support",()->{}));body.addView(action("Log out",()->login()));}
 void createPost(){base("Create post",false);postInput=field("Write something for your community...");postInput.setSingleLine(false);postInput.setMinHeight(150);body.addView(postInput);body.addView(action("Share post",()->{String s=postInput.getText().toString().trim();if(!s.isEmpty()){feed.add(0,s);screen("Home");}}));body.addView(action("Cancel",()->screen("Home")));}
 void findFriends(){screen("Friends");}
 View divider(){View v=new View(this);v.setBackgroundColor(0xffeae8f0);v.setLayoutParams(new LinearLayout.LayoutParams(-1,1));return v;}
}
